import{_ as a,o as s,c as t,a3 as o}from"./chunks/framework.DMtjdCb-.js";const m=JSON.parse('{"title":"2. Linux and Docker","description":"","frontmatter":{},"headers":[],"relativePath":"en/docker.md","filePath":"en/docker.md"}'),i={name:"en/docker.md"};function n(r,e,d,l,c,h){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="_2-linux-and-docker" tabindex="-1">2. Linux and Docker <a class="header-anchor" href="#_2-linux-and-docker" aria-label="Permalink to &quot;2. Linux and Docker&quot;">​</a></h1><p>The default stack runs four services: AnimeMachine for browsing and controls, Ani-RSS for subscriptions, qBittorrent for downloads, and Torrent Collector for Torrent searches. Connections and accounts are initialized automatically.</p><h2 id="prepare-a-project-folder" tabindex="-1">Prepare a project folder <a class="header-anchor" href="#prepare-a-project-folder" aria-label="Permalink to &quot;Prepare a project folder&quot;">​</a></h2><ol><li>Install <a href="https://docs.docker.com/engine/install/" target="_blank" rel="noreferrer">Docker Engine</a> and the <a href="https://docs.docker.com/compose/install/" target="_blank" rel="noreferrer">Compose plugin</a> for your Linux distribution. Use Docker Engine 24+ and Compose 2.20.3+.</li><li>Open a terminal on the computer or server that will run AnimeMachine.</li><li>Create a permanent project folder on a disk with enough space for your media:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/animemachine</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/animemachine</span></span></code></pre></div><p>The stack creates <code>config</code>, <code>data</code>, <code>library</code>, <code>torrents</code>, and <code>external</code> folders in this project. Media goes into <code>library</code> or <code>external/ani-rss</code>, so choose a disk with enough space.</p><h2 id="download-the-compose-file" tabindex="-1">Download the Compose file <a class="header-anchor" href="#download-the-compose-file" aria-label="Permalink to &quot;Download the Compose file&quot;">​</a></h2><p><a href="https://github.com/kyupi-git/animemachine/releases/latest/download/compose.yaml" target="_blank" rel="noreferrer">Download compose.yaml</a> and save it in the project folder. The release package also includes the same file at its root. Keep the complete file name <strong><code>compose.yaml</code></strong>. You can also download it in the terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/kyupi-git/animemachine/main/deploy/compose/compose.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.yaml</span></span></code></pre></div><p>Use one Compose file for the whole stack. No separate component accounts or configuration files are needed for the first start.</p><h2 id="use-a-terminal" tabindex="-1">Use a terminal <a class="header-anchor" href="#use-a-terminal" aria-label="Permalink to &quot;Use a terminal&quot;">​</a></h2><p>In the folder containing <code>compose.yaml</code>, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Check the services:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><p><strong>Expected result:</strong> all four services are running. Ani-RSS and the collector wait for AnimeMachine to become ready. The first command shows image download progress before starting the containers.</p><h2 id="open-the-page-and-find-your-password" tabindex="-1">Open the page and find your password <a class="header-anchor" href="#open-the-page-and-find-your-password" aria-label="Permalink to &quot;Open the page and find your password&quot;">​</a></h2><ol><li>Run the command below to find the initial account and random password.</li><li>On the same computer, open <strong><a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a></strong>. From another device, use the server&#39;s LAN address, such as <code>http://192.168.1.20:8787</code>.</li><li>Sign in and continue to <a href="./first-use.html">First login</a>.</li></ol><p>Read the startup log:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> animemachine</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Page</th><th>LAN address</th></tr></thead><tbody><tr><td>AnimeMachine</td><td><code>http://NAS-address:8787</code></td></tr><tr><td>Ani-RSS</td><td><code>http://NAS-address:7789</code></td></tr><tr><td>qBittorrent</td><td><code>http://NAS-address:8080</code></td></tr></tbody></table><p>Most operations are available in AnimeMachine. To open the other management pages, use <code>admin</code>; their initial passwords are in <code>config/ani-rss/.animemachine/web-password</code> and <code>config/qbittorrent/.animemachine/web-password</code> under the project folder.</p><h2 id="existing-services-and-other-disks" tabindex="-1">Existing services and other disks <a class="header-anchor" href="#existing-services-and-other-disks" aria-label="Permalink to &quot;Existing services and other disks&quot;">​</a></h2><p>If you already run Ani-RSS or qBittorrent, use <a href="https://github.com/kyupi-git/animemachine/tree/main/deploy/compose/templates" target="_blank" rel="noreferrer">preset 01 or 02</a>, then connect your service in <strong>Settings → Connections</strong>. The default file and the presets are alternative deployments; choose one.</p><p>For another media disk, follow <a href="./collections.html#docker-folders">folder mapping</a>. The full stack checks public source connectivity and selects an available alternate source when needed.</p><h2 id="common-deployment-questions" tabindex="-1">Common deployment questions <a class="header-anchor" href="#common-deployment-questions" aria-label="Permalink to &quot;Common deployment questions&quot;">​</a></h2><ul><li><strong>Configuration file not found:</strong> run the command in the folder containing <code>compose.yaml</code>; check that it is not named <code>compose.yaml.txt</code>.</li><li><strong>Image download failed:</strong> check the Docker error and retry the same command after restoring connectivity. Existing downloaded layers are reused.</li><li><strong>Docker permission denied:</strong> use an account with Docker access; if your installation requires it, run the Docker commands with <code>sudo</code>.</li><li><strong>Port is in use:</strong> put an unused port such as <code>ANM_WEB_PORT=8788</code> in a <code>.env</code> file alongside Compose, run <code>docker compose up -d</code>, and use port 8788 in the browser.</li><li><strong>Stopping temporarily:</strong> run <code>docker compose stop</code>. Settings, records, and media stay in the project folders.</li></ul>`,27)])])}const k=a(i,[["render",n]]);export{m as __pageData,k as default};
